CREATE PROCEDURE public.add_dlc(IN p_game_id integer, IN p_title text, IN p_description text, IN p_release_date date, IN p_price numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM game WHERE id = p_game_id) THEN
        RAISE EXCEPTION 'Игра с id=% не найдена', p_game_id;
    END IF;

    IF p_price < 0 THEN
        RAISE EXCEPTION 'Цена DLC не может быть отрицательной';
    END IF;

    VALUES (p_game_id, p_title, p_description, p_release_date, p_price);

    RAISE NOTICE 'DLC "%" для игры id=% добавлено', p_title, p_game_id;
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'DLC "%" для игры id=% уже существует', p_title, p_game_id;
END;
$$;


