CREATE PROCEDURE public.add_game_to_library(IN p_user_id integer, IN p_game_id integer, IN p_price numeric DEFAULT 0)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM app_user WHERE id = p_user_id) THEN
        RAISE EXCEPTION 'Пользователь id=% не найден', p_user_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM game WHERE id = p_game_id) THEN
        RAISE EXCEPTION 'Игра id=% не найдена', p_game_id;
    END IF;

    VALUES (p_user_id, p_game_id, p_price);

    RAISE NOTICE 'Игра id=% добавлена в библиотеку пользователя id=%', p_game_id, p_user_id;
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'У пользователя уже есть игра id=%', p_game_id;
END;
$$;


