-- TOC entry 278 (class 1255 OID 16648)
-- Name: buy_dlc(integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.buy_dlc(IN p_user_id integer, IN p_dlc_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_price     NUMERIC;
    v_balance   NUMERIC;
    v_game_id   INT;
    v_title     TEXT;
BEGIN
    SELECT balance INTO v_balance FROM app_user WHERE id = p_user_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Пользователь id=% не найден', p_user_id;
    END IF;

    SELECT price, game_id, title INTO v_price, v_game_id, v_title
    FROM dlc WHERE id = p_dlc_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'DLC id=% не найдено', p_dlc_id;
    END IF;

    -- Базовая игра должна быть в библиотеке
    IF NOT EXISTS (SELECT 1 FROM user_library
                   WHERE user_id = p_user_id AND game_id = v_game_id) THEN
        RAISE EXCEPTION 'Нельзя купить DLC без базовой игры id=%', v_game_id;
    END IF;

    IF EXISTS (SELECT 1 FROM user_dlc
               WHERE user_id = p_user_id AND dlc_id = p_dlc_id) THEN
        RAISE EXCEPTION 'DLC "%" уже куплено', v_title;
    END IF;

    IF v_balance < v_price THEN
        RAISE EXCEPTION 'Недостаточно средств: баланс=%, цена=%', v_balance, v_price;
    END IF;

    UPDATE app_user SET balance = balance - v_price WHERE id = p_user_id;

    VALUES (p_user_id, p_dlc_id, v_price);

    VALUES (p_user_id, 'purchase', v_price, 'Покупка DLC: ' || v_title);

    RAISE NOTICE 'DLC "%" куплено за %', v_title, v_price;
END;
$$;


ALTER PROCEDURE public.buy_dlc(IN p_user_id integer, IN p_dlc_id integer) OWNER TO postgres;

--
-- TOC entry 276 (class 1255 OID 16646)
-- Name: buy_game(integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.buy_game(IN p_user_id integer, IN p_game_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_price   NUMERIC;
    v_balance NUMERIC;
    v_title   TEXT;
BEGIN
    -- Проверка пользователя
    SELECT balance INTO v_balance
    FROM app_user WHERE id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Пользователь id=% не найден', p_user_id;
    END IF;

    -- Проверка игры
    SELECT price, title INTO v_price, v_title
    FROM game WHERE id = p_game_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Игра id=% не найдена', p_game_id;
    END IF;

    -- Проверка: не куплена ли уже
    IF EXISTS (SELECT 1 FROM user_library
               WHERE user_id = p_user_id AND game_id = p_game_id) THEN
        RAISE EXCEPTION 'Игра "%" уже есть в библиотеке', v_title;
    END IF;

    -- Проверка средств
    IF v_balance < v_price THEN
        RAISE EXCEPTION 'Недостаточно средств: баланс=%, цена=%', v_balance, v_price;
    END IF;

    -- Списание
    UPDATE app_user SET balance = balance - v_price WHERE id = p_user_id;

    -- Добавление в библиотеку
    VALUES (p_user_id, p_game_id, v_price);

    -- Запись в историю транзакций
    VALUES (p_user_id, 'purchase', v_price, 'Покупка игры: ' || v_title);

    RAISE NOTICE 'Покупка успешна: "%" за %', v_title, v_price;
END;
$$;


