--
-- TOC entry 260 (class 1255 OID 16652)
-- Name: can_buy(integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_buy(p_user_id integer, p_item_id integer, p_item_type text) RETURNS TABLE(can_purchase boolean, reason text)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_balance NUMERIC;
    v_price   NUMERIC;
    v_game_id INT;
BEGIN
    IF p_item_type NOT IN ('game', 'dlc') THEN
        RETURN QUERY SELECT FALSE, 'Неверный тип: ' || p_item_type;
        RETURN;
    END IF;

    SELECT balance INTO v_balance FROM app_user WHERE id = p_user_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Пользователь не найден';
        RETURN;
    END IF;

    IF p_item_type = 'game' THEN
        SELECT price INTO v_price FROM game WHERE id = p_item_id;
        IF NOT FOUND THEN
            RETURN QUERY SELECT FALSE, 'Игра не найдена';
            RETURN;
        END IF;

        IF EXISTS (SELECT 1 FROM user_library
                   WHERE user_id = p_user_id AND game_id = p_item_id) THEN
            RETURN QUERY SELECT FALSE, 'Игра уже в библиотеке';
            RETURN;
        END IF;
    ELSE
        SELECT price, game_id INTO v_price, v_game_id FROM dlc WHERE id = p_item_id;
        IF NOT FOUND THEN
            RETURN QUERY SELECT FALSE, 'DLC не найдено';
            RETURN;
        END IF;

        IF EXISTS (SELECT 1 FROM user_dlc
                   WHERE user_id = p_user_id AND dlc_id = p_item_id) THEN
            RETURN QUERY SELECT FALSE, 'DLC уже куплено';
            RETURN;
        END IF;

        IF NOT EXISTS (SELECT 1 FROM user_library
                       WHERE user_id = p_user_id AND game_id = v_game_id) THEN
            RETURN QUERY SELECT FALSE, 'Требуется базовая игра';
            RETURN;
        END IF;
    END IF;

    IF v_balance < v_price THEN
        RETURN QUERY SELECT FALSE,
            format('Недостаточно средств: нужно %, на счету %', v_price, v_balance);
        RETURN;
    END IF;

    RETURN QUERY SELECT TRUE, 'Покупка возможна';
END;
$$;


