-- Name: count_games_by_developer(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.count_games_by_developer(p_developer_name text) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_count INT;
BEGIN
    SELECT COUNT(DISTINCT gd.game_id)
    INTO v_count
    FROM developer d
    JOIN game_developer gd ON gd.developer_id = d.id
    WHERE d.name = p_developer_name;

    RETURN COALESCE(v_count, 0);
END;
$$;


