-- Name: deposit_balance(integer, numeric); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.deposit_balance(IN p_user_id integer, IN p_amount numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Сумма пополнения должна быть больше нуля';
    END IF;

    UPDATE app_user SET balance = balance + p_amount WHERE id = p_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Пользователь id=% не найден', p_user_id;
    END IF;

    VALUES (p_user_id, 'deposit', p_amount, 'Пополнение баланса');

    RAISE NOTICE 'Баланс пользователя id=% пополнен на %', p_user_id, p_amount;
END;
$$;


