--
-- TOC entry 255 (class 1255 OID 16651)
-- Name: games_by_publisher_period(text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.games_by_publisher_period(p_publisher_name text, p_date_from date, p_date_to date) RETURNS TABLE(game_id integer, title text, release_date date, price numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT g.id, g.title, g.release_date, g.price
    FROM publisher p
    JOIN game_publisher gp ON gp.publisher_id = p.id
    JOIN game g           ON g.id = gp.game_id
    WHERE p.name = p_publisher_name
      AND g.release_date BETWEEN p_date_from AND p_date_to
    ORDER BY g.release_date;
END;
$$;


