    LANGUAGE plpgsql
    AS $$
DECLARE
    v_game_id INT;
BEGIN
    SELECT game_id INTO v_game_id FROM achievement WHERE id = p_achievement_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Достижение id=% не найдено', p_achievement_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM user_library
                   WHERE user_id = p_user_id AND game_id = v_game_id) THEN
        RAISE EXCEPTION 'У пользователя нет игры, к которой относится достижение';
    END IF;

    VALUES (p_user_id, p_achievement_id);

    RAISE NOTICE 'Достижение id=% выдано пользователю id=%',
        p_achievement_id, p_user_id;
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'Достижение уже получено';
END;
$$;


