--
-- TOC entry 281 (class 1255 OID 16705)
-- Name: process_game_refund(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_game_refund() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
   v_purchase_price NUMERIC(10,2);
   v_purchase_date DATE;
   v_time_played INTERVAL;
   v_last_date_played DATE;
BEGIN
   -- Получаем сведения о покупке из библиотеки
   SELECT purchase_price, purchase_date,
          time_played, last_date_played
   INTO v_purchase_price, v_purchase_date,
        v_time_played, v_last_date_played
   FROM user_library
   WHERE user_id = NEW.user_id
     AND game_id = NEW.game_id
   FOR UPDATE;
   -- Если игры нет в библиотеке, автоматический возврат невозможен
   IF NOT FOUND THEN
       NEW.purchase_price := 0;
       NEW.status := 'rejected';
       RETURN NEW;
   END IF;
   -- Сохраняем фактическую цену покупки,
   -- которая могла отличаться от текущей цены игры
   NEW.purchase_price := v_purchase_price;
   -- Проверяем условия автоматического возврата:
   -- 1. Игра не запускалась в течение месяца после покупки
   --    либо последний запуск состоялся в первые 14 дней.
   -- 2. Общее время игры не превышает двух часов.
   IF v_time_played <= INTERVAL '2 hours'
      AND (
          (
              v_last_date_played IS NULL
              AND CURRENT_DATE <=
                  v_purchase_date + INTERVAL '1 month'
          )
          OR
          (
              v_last_date_played >= v_purchase_date
              AND v_last_date_played <=
                  v_purchase_date + 14
          )
      )
   THEN
       -- Возвращаем деньги на баланс пользователя
       UPDATE app_user
       SET balance = balance + v_purchase_price
       WHERE id = NEW.user_id;
       -- Записываем возврат в историю операций
           user_id,
           transaction_type,
           amount,
           description
       )
       VALUES (
           NEW.user_id,
           'refund',
           v_purchase_price,
           'Возврат игры id=' || NEW.game_id
       );
       -- Удаляем игру из библиотеки пользователя
       DELETE FROM user_library
       WHERE user_id = NEW.user_id
         AND game_id = NEW.game_id;
       -- Отмечаем автоматический возврат
       NEW.status := 'auto_refunded';
   ELSE
       -- Запрос сохраняется для ручной проверки
       NEW.status := 'manual_review';
   END IF;
   RETURN NEW;
END;
$$;


ALTER FUNCTION public.process_game_refund() OWNER TO postgres;

