-- TOC entry 250 (class 1255 OID 16654)
-- Name: top_games_by_sales(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.top_games_by_sales(p_limit integer DEFAULT 10) RETURNS TABLE(game_id integer, title text, sales_cnt bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT g.id, g.title, COUNT(ul.id) AS sales_cnt
    FROM game g
    LEFT JOIN user_library ul ON ul.game_id = g.id
    GROUP BY g.id, g.title
    ORDER BY sales_cnt DESC
    LIMIT p_limit;
$$;


