CREATE PROCEDURE public.update_dlc(IN p_id integer, IN p_title text DEFAULT NULL::text, IN p_description text DEFAULT NULL::text, IN p_release_date date DEFAULT NULL::date, IN p_price numeric DEFAULT NULL::numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dlc WHERE id = p_id) THEN
        RAISE EXCEPTION 'DLC с id=% не найдено', p_id;
    END IF;

    UPDATE dlc
    SET title        = COALESCE(p_title, title),
        description  = COALESCE(p_description, description),
        release_date = COALESCE(p_release_date, release_date),
        price        = COALESCE(p_price, price)
    WHERE id = p_id;

    RAISE NOTICE 'DLC id=% обновлено', p_id;
END;
$$;


