--
-- TOC entry 252 (class 1255 OID 16643)
-- Name: update_playtime(integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.update_playtime(IN p_user_id integer, IN p_game_id integer, IN p_add_minutes integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_add_minutes < 0 THEN
        RAISE EXCEPTION 'Добавляемое время не может быть отрицательным';
    END IF;

    UPDATE user_library
    SET time_played      = time_played + make_interval(mins => p_add_minutes),
        last_date_played = CURRENT_DATE
    WHERE user_id = p_user_id AND game_id = p_game_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Игра id=% отсутствует в библиотеке пользователя id=%',
            p_game_id, p_user_id;
    END IF;

    RAISE NOTICE 'К игра id=% пользователя id=% добавлено % мин',
        p_game_id, p_user_id, p_add_minutes;
END;
$$;


