--
-- TOC entry 280 (class 1255 OID 16655)
-- Name: user_achievement_progress(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_achievement_progress(p_user_id integer, p_game_id integer) RETURNS TABLE(total_achievements integer, unlocked_achievements integer, progress_percent numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_total    INT;
    v_unlocked INT;
BEGIN
    -- Проверка: есть ли игра у пользователя
    IF NOT EXISTS (
        SELECT 1 FROM user_library
        WHERE user_id = p_user_id AND game_id = p_game_id
    ) THEN
        RAISE EXCEPTION 'Игра id=% отсутствует в библиотеке пользователя id=%',
            p_game_id, p_user_id;
    END IF;

    -- Всего достижений в игре
    SELECT COUNT(*) INTO v_total
    FROM achievement
    WHERE game_id = p_game_id;

    -- Получено пользователем
    SELECT COUNT(*) INTO v_unlocked
    FROM user_achievement ua
    JOIN achievement a ON a.id = ua.achievement_id
    WHERE ua.user_id = p_user_id
      AND a.game_id   = p_game_id;

    -- Процент (защита от деления на ноль)
    RETURN QUERY
    SELECT
        v_total,
        v_unlocked,
        CASE
            WHEN v_total = 0 THEN 0::numeric
            ELSE ROUND((v_unlocked::numeric / v_total) * 100, 2)
        END;
END;
$$;


ALTER FUNCTION public.user_achievement_progress(p_user_id integer, p_game_id integer) OWNER TO postgres;

--
-- TOC entry 267 (class 1255 OID 16653)
-- Name: user_total_spent(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.user_total_spent(p_user_id integer) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sum NUMERIC;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_sum
    FROM transaction_history
    WHERE user_id = p_user_id
      AND transaction_type = 'purchase';

    RETURN v_sum;
END;
$$;


ALTER FUNCTION public.user_total_spent(p_user_id integer) OWNER TO postgres;

