--
-- TOC entry 243 (class 1259 OID 16656)
-- Name: v_game_full_info; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_game_full_info AS
 SELECT id,
    title,
    release_date,
    price,
    short_description,
    COALESCE(( SELECT string_agg(d.name, ', '::text ORDER BY d.name) AS string_agg
           FROM (public.game_developer gd
             JOIN public.developer d ON ((d.id = gd.developer_id)))
          WHERE (gd.game_id = g.id)), '—'::text) AS developers,
    COALESCE(( SELECT string_agg(p.name, ', '::text ORDER BY p.name) AS string_agg
           FROM (public.game_publisher gp
             JOIN public.publisher p ON ((p.id = gp.publisher_id)))
          WHERE (gp.game_id = g.id)), '—'::text) AS publishers
   FROM public.game g;


ALTER VIEW public.v_game_full_info OWNER TO postgres;

--
-- TOC entry 245 (class 1259 OID 16666)
-- Name: v_game_sales_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_game_sales_summary AS
 SELECT g.id,
    g.title,
    g.price AS current_price,
    count(ul.id) AS copies_sold,
    COALESCE(sum(ul.purchase_price), (0)::numeric) AS total_revenue,
    COALESCE(round(avg(ul.purchase_price), 2), (0)::numeric) AS avg_purchase_price,
    count(DISTINCT ul.user_id) AS unique_buyers
   FROM (public.game g
     LEFT JOIN public.user_library ul ON ((ul.game_id = g.id)))
  GROUP BY g.id, g.title, g.price;


ALTER VIEW public.v_game_sales_summary OWNER TO postgres;

--
-- TOC entry 246 (class 1259 OID 16671)
-- Name: v_user_activity; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_user_activity AS
 SELECT u.id,
    u.username,
    u.email,
    u.balance,
    u.sign_up_date,
    count(DISTINCT ul.game_id) AS games_owned,
    COALESCE(sum((EXTRACT(epoch FROM ul.time_played) / (3600)::numeric)), (0)::numeric) AS total_hours,
    count(DISTINCT ua.achievement_id) AS achievements_unlocked
   FROM ((public.app_user u
     LEFT JOIN public.user_library ul ON ((ul.user_id = u.id)))
     LEFT JOIN public.user_achievement ua ON ((ua.user_id = u.id)))
  GROUP BY u.id, u.username, u.email, u.balance, u.sign_up_date;


ALTER VIEW public.v_user_activity OWNER TO postgres;

--
-- TOC entry 244 (class 1259 OID 16661)
-- Name: v_user_library_detailed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_user_library_detailed AS
 SELECT ul.id,
    u.username,
    g.title AS game_title,
    ul.purchase_price,
    ul.purchase_date,
    ul.time_played,
    ul.last_date_played,
    (EXTRACT(epoch FROM ul.time_played) / (3600)::numeric) AS hours_played
   FROM ((public.user_library ul
     JOIN public.app_user u ON ((u.id = ul.user_id)))
     JOIN public.game g ON ((g.id = ul.game_id)));


ALTER VIEW public.v_user_library_detailed OWNER TO postgres;

